export async function fetchPage(cursor?: string): Promise<Page> {
  const url = new URL('/api/items', location.origin)
  if (cursor) url.searchParams.set('cursor', cursor)
  const response = await fetch(url, { headers: { Accept: 'application/json' } })
  if (!response.ok) throw new Error(`Request failed: ${response.status}`)
  return response.json() as Promise<Page>
}

from collections import defaultdict

def summarize(events):
    totals = defaultdict(int)
    for event in events:
        if event.get('status') == 'complete':
            totals[event['project_id']] += event.get('bytes', 0)
    return sorted(totals.items(), key=lambda row: row[1], reverse=True)

assert summarize([]) == []
